package com.sistemahospitalar.hospital.controller; import com.sistemahospitalar.hospital.model.Quarto; import com.sistemahospitalar.hospital.service.QuartoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/quartos") public class QuartoController {private final QuartoService service; public QuartoController(QuartoService s){service=s;} @GetMapping public List<Quarto> listar(){return service.listar();} @PostMapping public ResponseEntity<Quarto> criar(@Valid @RequestBody Quarto q){return ResponseEntity.status(HttpStatus.CREATED).body(service.salvar(q));} }
